CREATE TABLE commercial_customers (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE, name text NOT NULL, email text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX commercial_customers_company_idx ON commercial_customers(company_id, name);
CREATE TABLE commercial_documents (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN ('quote','invoice','vendor_bill')), number text NOT NULL, counterparty_id uuid REFERENCES commercial_customers(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','issued','paid','void')), issue_date date NOT NULL, due_date date, currency text NOT NULL DEFAULT 'IDR', total_cents bigint NOT NULL DEFAULT 0 CHECK(total_cents >= 0), notes text NOT NULL DEFAULT '', created_by uuid REFERENCES users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id, number));
CREATE INDEX commercial_documents_company_idx ON commercial_documents(company_id, kind, issue_date DESC);
CREATE TABLE commercial_document_lines (id uuid PRIMARY KEY, document_id uuid NOT NULL REFERENCES commercial_documents(id) ON DELETE CASCADE, description text NOT NULL, quantity numeric(14,3) NOT NULL CHECK(quantity > 0), unit_price_cents bigint NOT NULL CHECK(unit_price_cents >= 0), total_cents bigint NOT NULL CHECK(total_cents >= 0));
CREATE TABLE commercial_payments (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE, document_id uuid NOT NULL REFERENCES commercial_documents(id) ON DELETE CASCADE, paid_at timestamptz NOT NULL DEFAULT now(), amount_cents bigint NOT NULL CHECK(amount_cents > 0), method text NOT NULL DEFAULT 'transfer', reference text NOT NULL DEFAULT '', created_by uuid REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE pos_products (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE, sku text NOT NULL, name text NOT NULL, price_cents bigint NOT NULL CHECK(price_cents >= 0), stock_qty integer NOT NULL DEFAULT 0, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id, sku));
CREATE TABLE pos_sales (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE, receipt_number text NOT NULL, status text NOT NULL DEFAULT 'paid' CHECK(status IN ('paid','void','refunded')), total_cents bigint NOT NULL CHECK(total_cents >= 0), payment_method text NOT NULL DEFAULT 'cash', cashier_id uuid REFERENCES users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id, receipt_number));
CREATE TABLE pos_sale_lines (id uuid PRIMARY KEY, sale_id uuid NOT NULL REFERENCES pos_sales(id) ON DELETE CASCADE, product_id uuid REFERENCES pos_products(id) ON DELETE SET NULL, product_name text NOT NULL, quantity integer NOT NULL CHECK(quantity > 0), unit_price_cents bigint NOT NULL CHECK(unit_price_cents >= 0), total_cents bigint NOT NULL CHECK(total_cents >= 0));
CREATE TABLE device_sync_devices (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, device_key_hash text NOT NULL, label text NOT NULL DEFAULT '', platform text NOT NULL DEFAULT 'unknown', last_cursor bigint NOT NULL DEFAULT 0, last_seen_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id, device_key_hash));
CREATE TABLE device_sync_mutations (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE, device_id uuid NOT NULL REFERENCES device_sync_devices(id) ON DELETE CASCADE, idempotency_key text NOT NULL, resource_type text NOT NULL, resource_id uuid NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, applied_at timestamptz NOT NULL DEFAULT now(), UNIQUE(device_id, idempotency_key));
CREATE INDEX device_sync_mutations_company_idx ON device_sync_mutations(company_id, applied_at DESC);
